def clean(s):return ' '.join(html.unescape(re.sub('<[^>]+>','',s)).split())
def lineof(t,pos):return t.count('\n',0,pos)+1
def page_before(t,pos):
 found=re.findall(r'<a id="page_(\d+)"',t[:pos]);return found[-1] if found else None
facts=[];held=[];coverage=[]
for ch,d in D.items():
 src=R/f'raw/nas_memoirs_chapter_{ch:02}.html';raw=src.read_bytes();t=raw.decode('utf-8').replace('\\"','"');meta=META[ch];sha=hashlib.sha256(raw).hexdigest();assert sha==meta['original_bytes_sha256']
 headings=list(re.finditer(r'<h2 class="chaptertitle">(.*?)</h2>',t,re.S));title=clean(headings[0][1]);life_m=re.search(r'<p class="chaptertitlesub">(.*?)</p>',t,re.S);life=clean(life_m[1]);dobtext=life.split('–')[0];source_dob=datetime.datetime.strptime(dobtext,'%B %d, %Y').date().isoformat()
 paras=[]
 for m in re.finditer(r'<p[^>]*class="([^"]+)"[^>]*>(.*?)</p>',t,re.S):
  s=clean(m[2])
